    {"id": "u12-g4", "question": "The engineer promised _____ the offshore wind turbine maintenance report by Friday.", "options": ["A. to deliver", "B. delivering", "C. deliver", "D. delivered"], "correctAnswer": "A. to deliver", "explanation": "Cấu trúc: 'promise + to V' -> 'promised to deliver'."},
    {"id": "u12-g5", "question": "The mentor encouraged the students _____ up programming as a lifelong career path.", "options": ["A. to take", "B. taking", "C. take", "D. took"], "correctAnswer": "A. to take", "explanation": "Cấu trúc: 'encourage + O + to V' -> 'encouraged the students to take up'."},
    {"id": "u12-g6", "question": "The cybersecurity firm warned its clients against _____ unverified software applications.", "options": ["A. downloading", "B. to download", "C. download", "D. downloaded"], "correctAnswer": "A. downloading", "explanation": "Cấu trúc: 'warn sb against + V-ing' -> 'against downloading'."},
    {"id": "u12-g7", "question": "He apologized to his team leader for _____ late for the critical strategy meeting.", "options": ["A. arriving", "B. to arrive", "C. arrive", "D. arrived"], "correctAnswer": "A. arriving", "explanation": "Cấu trúc: 'apologize (to sb) for + V-ing' -> 'for arriving'."},
    {"id": "u12-g8", "question": "The doctor suggested _____ a healthier work-life balance to reduce chronic stress.", "options": ["A. adopting", "B. to adopt", "C. adopt", "D. adopted"], "correctAnswer": "A. adopting", "explanation": "Cấu trúc: 'suggest + V-ing' -> 'suggested adopting'."},
    {"id": "u12-g9", "question": "My father reminded me _____ my professional resume before submitting it online.", "options": ["A. to proofread", "B. proofreading", "C. proofread", "D. proofreaded"], "correctAnswer": "A. to proofread", "explanation": "Cấu trúc: 'remind + O + to V' -> 'reminded me to proofread'."},
    {"id": "u12-g10", "question": "The young entrepreneur refused _____ up her sustainable fashion startup despite initial difficulties.", "options": ["A. to give", "B. giving", "C. give", "D. gave"], "correctAnswer": "A. to give", "explanation": "Cấu trúc: 'refuse + to V' -> 'refused to give up'."},
    {"id": "u12-g11", "question": "We are eagerly looking forward to _____ our research internship at the National AI Center.", "options": ["A. commencing", "B. commence", "C. to commence", "D. commenced"], "correctAnswer": "A. commencing", "explanation": "Cấu trúc: 'look forward to + V-ing' -> 'to commencing'."},
    {"id": "u12-g12", "question": "The data scientist insisted on _____ the algorithm test three times to verify precision.", "options": ["A. running", "B. to run", "C. run", "D. ran"], "correctAnswer": "A. running", "explanation": "Cấu trúc: 'insist on + V-ing' -> 'on running'."},
    {"id": "u12-g13", "question": "The teacher offered _____ the student understand complex biochemical concepts after class.", "options": ["A. to help", "B. helping", "C. help", "D. helped"], "correctAnswer": "A. to help", "explanation": "Cấu trúc: 'offer + to V' -> 'offered to help'."},
    {"id": "u12-g14", "question": "The recruitment officer invited the outstanding candidate _____ the final round interview.", "options": ["A. to attend", "B. attending", "C. attend", "D. attended"], "correctAnswer": "A. to attend", "explanation": "Cấu trúc: 'invite + O + to V' -> 'invited the candidate to attend'."},
    {"id": "u12-g15", "question": "He denied _____ company confidential blueprints to external competitors.", "options": ["A. disclosing", "B. to disclose", "C. disclose", "D. disclosed"], "correctAnswer": "A. disclosing", "explanation": "Cấu trúc: 'deny + V-ing' -> 'denied disclosing'."},
    {"id": "u12-g16", "question": "Young professionals must continuously update their skills to keep _____ with rapid technological changes.", "options": ["A. up", "B. on", "C. off", "D. out"], "correctAnswer": "A. up", "explanation": "Cụm động từ: 'keep up with' có nghĩa là theo kịp, bắt kịp."},
